import * as THREE from 'three';

export const SPONSOR_DATA = [
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
];

export const SPONSOR_COLORS = [
  0xfed100, // Pirelli Yellow
  0x00358e, // Michelin Blue
  0xf5f6f8, // Mobil 1 White
  0x091b32, // Traced Navy
  0x0e1018, // PalomApp oscuro
];

let cachedTextures = null;
export function getSponsorTextures() {
  if (cachedTextures) return cachedTextures;
  if (typeof document === 'undefined') return [];
  const loader = new THREE.TextureLoader();
  cachedTextures = SPONSOR_DATA.map(data => {
    const tex = loader.load(data);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    return tex;
  });
  return cachedTextures;
}

export function getSponsorTexture(idx) {
  const list = getSponsorTextures();
  if (!list || !list.length) return null;
  return list[idx % list.length];
}
